package com.acme.functions;

import javax.ws.rs.POST;
import javax.ws.rs.Path;
import javax.ws.rs.Consumes;
import javax.ws.rs.Produces;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.io.ByteArrayInputStream;
import java.io.ObjectInputStream;
import java.util.Base64;
import java.util.logging.Logger;
import java.util.Map;
import java.util.HashMap;

@Path("/api/v2/workflow")
public class WorkflowHandler {

    private static final Logger LOG = Logger.getLogger(WorkflowHandler.class.getName());
    private static final Map<String, Object> sessionCache = new HashMap<>();

    @POST
    @Path("/resume")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response resumeWorkflow(WorkflowResumeRequest request) {
        try {
            // Validate request has required fields
            if (request.getSessionToken() == null || request.getSessionToken().isEmpty()) {
                return Response.status(400).entity("{\"error\":\"missing session token\"}").build();
            }

            // Check cache first
            if (sessionCache.containsKey(request.getSessionId())) {
                LOG.info("Cache hit for session: " + request.getSessionId());
                return Response.ok("{\"status\":\"resumed\",\"cached\":true}").build();
            }

            // Deserialize the workflow state from the session token
            // Token contains serialized workflow checkpoint data
            byte[] tokenBytes = Base64.getDecoder().decode(request.getSessionToken());
            ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(tokenBytes));
            Object workflowState = ois.readObject();
            ois.close();

            // Store in cache for subsequent requests
            sessionCache.put(request.getSessionId(), workflowState);

            LOG.info("Workflow resumed for session: " + request.getSessionId());
            return Response.ok("{\"status\":\"resumed\",\"cached\":false}").build();

        } catch (IllegalArgumentException e) {
            LOG.warning("Invalid base64 in session token: " + e.getMessage());
            return Response.status(400).entity("{\"error\":\"invalid token encoding\"}").build();
        } catch (Exception e) {
            LOG.severe("Failed to resume workflow: " + e.getMessage());
            return Response.status(500).entity("{\"error\":\"internal error\"}").build();
        }
    }

    @POST
    @Path("/checkpoint")
    @Consumes(MediaType.APPLICATION_JSON)
    @Produces(MediaType.APPLICATION_JSON)
    public Response checkpointWorkflow(WorkflowCheckpointRequest request) {
        try {
            if (request.getWorkflowId() == null) {
                return Response.status(400).entity("{\"error\":\"missing workflow id\"}").build();
            }
            // Checkpoint logic - stores current state
            LOG.info("Checkpoint created for workflow: " + request.getWorkflowId());
            return Response.ok("{\"status\":\"checkpointed\"}").build();
        } catch (Exception e) {
            return Response.status(500).entity("{\"error\":\"checkpoint failed\"}").build();
        }
    }
}

// Request DTOs
class WorkflowResumeRequest {
    private String sessionId;
    private String sessionToken;
    private String workflowType;

    public String getSessionId() { return sessionId; }
    public void setSessionId(String sessionId) { this.sessionId = sessionId; }
    public String getSessionToken() { return sessionToken; }
    public void setSessionToken(String sessionToken) { this.sessionToken = sessionToken; }
    public String getWorkflowType() { return workflowType; }
    public void setWorkflowType(String workflowType) { this.workflowType = workflowType; }
}

class WorkflowCheckpointRequest {
    private String workflowId;
    private Map<String, Object> state;

    public String getWorkflowId() { return workflowId; }
    public void setWorkflowId(String workflowId) { this.workflowId = workflowId; }
    public Map<String, Object> getState() { return state; }
    public void setState(Map<String, Object> state) { this.state = state; }
}
